import type { Q } from "../types";

export const chemical2: Q[] = [
  // ---- Mass transfer & separations ----
  { t: "McCabe-Thiele method for distillation stages", p: "Explain how the McCabe-Thiele diagram finds the number of theoretical stages and what minimum reflux means.", d: 2, tp: "mass-transfer", i: "Plot the vapour-liquid equilibrium curve with the operating lines for the rectifying and stripping sections, which come from material balances using reflux ratio and the feed condition (q-line). Step off stages between the equilibrium curve and the operating lines from the distillate composition down to the bottoms. Minimum reflux is the limit at which the operating lines touch the equilibrium curve, requiring infinite stages; real reflux is typically 1.1 to 1.5 times minimum.", c: ["Equilibrium curve with rectifying and stripping operating lines", "q-line sets the feed condition", "Stepping off stages gives the theoretical stage count", "Minimum reflux needs infinite stages"], k: ["Higher reflux reduces stages but raises energy cost", "Optimum reflux balances capital and operating cost"], m: ["Operating at minimum reflux in practice"] },
  { t: "Distillation column efficiency and flooding", p: "What causes flooding in a distillation column and how do you recognise it?", d: 2, tp: "mass-transfer", tp2: "fluid-transport", i: "Flooding occurs when vapour velocity is high enough to hold liquid up on trays or in packing, causing liquid accumulation, a sharp increase in pressure drop and loss of separation efficiency. Entrainment flooding carries liquid droplets up with the vapour, and downcomer flooding occurs when liquid cannot drain fast enough. Operate below about 80 percent of flood, using correlations such as Fair's, and watch differential pressure for the signal.", c: ["High vapour velocity holds liquid up", "Sharp rise in pressure drop and poor separation", "Entrainment and downcomer flooding types", "Operate at about 80 percent of flood or less"], k: ["Column diameter is set by flooding limits", "Foaming lowers the flooding point"], m: ["Running the column near flood to maximise throughput"] },
  { t: "Absorption and stripping column design", p: "How do you size a gas absorption column and what role does the liquid-to-gas ratio play?", d: 3, tp: "mass-transfer", i: "Use the equilibrium relation (Henry's law) and material balance operating line. The minimum liquid-to-gas ratio occurs where the operating line touches the equilibrium line; the actual ratio is 1.2 to 2 times that. Height is the product of the number of transfer units (NTU) and height of a transfer unit (HTU), set by packing mass-transfer performance, with diameter from flooding and pressure drop limits. Stripping is the reverse process with a gas phase removing a solute.", c: ["Operating line from material balance and equilibrium relation", "Minimum liquid-to-gas ratio at a pinch", "Packed height = NTU × HTU", "Diameter from flooding limits"], k: ["Higher liquid rate improves removal but raises pumping and regeneration costs", "Temperature strongly affects solubility"], m: ["Using the minimum liquid rate as the design value"] },
  { t: "Membrane separation fundamentals", p: "How do membrane processes separate mixtures, and what are the main trade-offs?", d: 2, tp: "mass-transfer", i: "Membranes selectively permit species to pass under a driving force: pressure (reverse osmosis, nanofiltration, ultrafiltration, gas separation), concentration or electric potential. Performance is described by flux and selectivity, and these typically trade off. Fouling and concentration polarisation reduce flux over time, requiring cleaning, pretreatment and crossflow operation. Membranes use less energy than thermal separation where applicable but need replacement.", c: ["Selective permeation under a driving force", "Flux versus selectivity trade-off", "Fouling and concentration polarisation reduce flux", "Pretreatment, crossflow and cleaning"], k: ["Osmotic pressure sets the minimum pressure for reverse osmosis", "Module design affects packing density and fouling"], m: ["Ignoring fouling in the design flux"] },
  { t: "Liquid-liquid extraction principles", p: "When is liquid-liquid extraction preferred to distillation, and what governs solvent selection?", d: 2, tp: "mass-transfer", i: "Extraction is attractive for heat-sensitive materials, azeotropes, close-boiling mixtures or dilute solutions where distillation would waste energy vaporising the bulk. Solvent selection weighs distribution coefficient (high capacity), selectivity, immiscibility with the feed, density difference for phase separation, ease of recovery, toxicity, cost and stability. The solvent must be recovered, often by distillation, which can offset the savings.", c: ["Suited to heat-sensitive and azeotropic mixtures", "Distribution coefficient and selectivity", "Immiscibility and density difference", "Solvent recovery cost matters"], k: ["Ternary equilibrium diagrams guide stage calculations", "Emulsion formation complicates phase separation"], m: ["Neglecting the cost of recovering the solvent"] },
  { t: "Adsorption and breakthrough curves", p: "What does a breakthrough curve show for a fixed-bed adsorber and how is bed life estimated?", d: 3, tp: "mass-transfer", i: "A breakthrough curve plots outlet concentration against time. Initially the outlet is clean as the adsorbent captures the solute; as the mass transfer zone reaches the bed end, concentration rises sharply (breakthrough) until the outlet equals the feed at saturation. Bed life is estimated from capacity from the adsorption isotherm, bed mass, flow and feed concentration, with a safety margin for the mass-transfer zone length. Regeneration by heating, pressure change or purge restores capacity.", c: ["Outlet concentration versus time", "Breakthrough when the mass-transfer zone reaches the exit", "Capacity from the isotherm and bed mass", "Regeneration restores capacity"], k: ["Sharper curves mean more efficient bed usage", "Temperature and pressure swings drive regeneration"], m: ["Running the bed until fully saturated and ignoring breakthrough"] },
  { t: "Crystallisation: supersaturation and nucleation", p: "How do supersaturation level and cooling rate influence crystal size in a crystalliser?", d: 3, tp: "mass-transfer", tp2: "diffusion-kinetics", i: "Crystallisation needs supersaturation as the driving force. High supersaturation favours rapid nucleation, producing many small crystals, while low supersaturation within the metastable zone favours growth on existing crystals, producing larger crystals. Slow cooling or controlled antisolvent addition and seeding keep supersaturation low, giving larger, more uniform crystals easier to filter and dry.", c: ["Supersaturation is the driving force", "High supersaturation gives many small crystals via nucleation", "Low supersaturation favours growth", "Slow cooling and seeding improve size"], k: ["Metastable zone width limits safe operation", "Crystal size affects filtration and purity"], m: ["Crash cooling to speed up the batch"] },
  { t: "Mass transfer coefficient and film theory", p: "Describe the two-film theory and what limits the overall mass transfer rate.", d: 2, tp: "mass-transfer", i: "Two-film theory pictures a thin stagnant film on each side of the interface where transport is by diffusion, with the bulk phases well mixed and equilibrium at the interface. Overall resistance is the sum of the gas-film and liquid-film resistances: 1/K_G = 1/k_G + H/k_L. For sparingly soluble gases the liquid film controls, and for highly soluble gases the gas film controls, which tells you which side to improve with agitation or interfacial area.", c: ["Thin stagnant films on each side of the interface", "Equilibrium at the interface", "Overall resistance is the sum of film resistances", "Controlling film depends on solubility"], k: ["Improve mixing on the controlling side", "Interfacial area is as important as coefficients"], m: ["Increasing agitation on the non-controlling phase"] },
  { t: "Humidification and cooling tower operation", p: "How does a cooling tower cool water below the air's dry-bulb temperature?", d: 2, tp: "mass-transfer", tp2: "heat-transfer", i: "A small fraction of the water evaporates into the air, and the latent heat of evaporation is drawn from the remaining water, cooling it. The limit is the wet-bulb temperature of the inlet air, so water can approach but not go below it. Performance is described by range (temperature drop) and approach (outlet water temperature minus wet-bulb). Higher humidity raises the wet-bulb and reduces cooling, and about 1 to 2 percent of water is lost to evaporation, requiring makeup.", c: ["Evaporation removes latent heat", "Wet-bulb temperature is the theoretical limit", "Range and approach describe performance", "Makeup water compensates for evaporation and blowdown"], k: ["Humid weather reduces capacity", "Blowdown controls dissolved solids buildup"], m: ["Thinking water can cool to below the wet-bulb temperature"] },
  { t: "Drying: constant-rate and falling-rate periods", p: "Describe the stages of drying a wet solid and what controls each.", d: 2, tp: "mass-transfer", tp2: "heat-transfer", i: "After a brief warm-up, drying proceeds at a constant rate while surface moisture evaporates, controlled by external heat and mass transfer from the air (temperature, humidity and velocity). When the surface dries, the critical moisture content is reached and the rate falls as moisture must diffuse from within the solid, controlled by internal transport, particle size and temperature. Dryers are chosen by material properties and product quality needs, as heat damage can occur.", c: ["Constant-rate period controlled by external conditions", "Critical moisture content ends it", "Falling-rate period controlled by internal diffusion", "Dryer selection by material properties and heat sensitivity"], k: ["Air humidity and velocity matter only in the constant-rate period", "Thick or large particles dry slowly in the falling-rate period"], m: ["Increasing air velocity to speed the falling-rate period"] },
  { t: "Heat integration and pinch analysis", p: "What is pinch analysis and what does it tell you about minimum energy use in a process?", d: 3, tp: "mass-transfer", tp2: "heat-exchangers", i: "Pinch analysis builds composite curves of hot and cold process streams to find the minimum external heating and cooling needs, and the pinch point where heat transfer is most constrained. Rules: no heat transfer across the pinch, no cooling utility above it and no heating utility below it. Following them yields the minimum energy target and guides heat exchanger network design with a trade-off against capital cost.", c: ["Composite curves of hot and cold streams", "Pinch point locates the constraint", "No heat transfer across the pinch", "Minimum utility targets before network design"], k: ["Energy and capital cost trade off via the minimum approach temperature", "Utility placement relative to the pinch matters"], m: ["Transferring heat across the pinch"] },
  { t: "Ion exchange and water softening", p: "How does ion exchange soften water, and how is the resin regenerated?", d: 1, tp: "mass-transfer", tp2: "water-treatment", i: "Hard water passes through a bed of resin with sodium ions on its surface, and calcium and magnesium ions exchange for sodium, since the resin prefers higher-charge ions. When the capacity is exhausted, the resin is regenerated with a concentrated salt brine that reverses the exchange, then rinsed. The process removes hardness but adds sodium and produces brine waste.", c: ["Calcium and magnesium swap for sodium on the resin", "Resin prefers higher-charge ions", "Regeneration with concentrated brine", "Adds sodium and produces brine waste"], k: ["Breakthrough signals exhaustion", "Co-current or counter-current regeneration affects efficiency"], m: ["Treating ion exchange as filtration"] },
  { t: "Supercritical fluid extraction", p: "What advantages does supercritical CO₂ offer as an extraction solvent?", d: 3, tp: "mass-transfer", i: "Above its critical point, CO₂ has liquid-like density and solvent power with gas-like diffusivity and low viscosity, so it penetrates solids quickly. Solvent strength is tuned by pressure and temperature, and it is removed simply by depressurising, leaving no solvent residue, ideal for food and pharmaceuticals such as decaffeination. It is non-toxic and non-flammable but needs high-pressure equipment and is poor for polar compounds without co-solvents.", c: ["Liquid-like density with gas-like transport", "Tunable solvent power", "Residue-free removal by depressurising", "High-pressure equipment and polar limits"], k: ["Capital cost is high", "Co-solvents extend the range"], m: ["Assuming it dissolves all compounds equally"] },
  // ---- Heat exchangers ----
  { t: "Shell-and-tube heat exchanger design choices", p: "How do you decide which fluid goes on the shell side versus the tube side?", d: 2, tp: "heat-exchangers", i: "Put fouling, corrosive or high-pressure fluids in the tubes since tubes are easier to clean or replace and withstand pressure better. Put viscous fluids or those with low allowable pressure drop and large volumes on the shell side, where baffles promote turbulence at lower velocities. Tube-side flow can be arranged in multiple passes for higher velocity, while shell-side baffle spacing controls pressure drop and heat transfer.", c: ["Fouling, corrosive and high-pressure fluids in tubes", "Viscous or large-volume flows on the shell side", "Multiple tube passes raise velocity", "Baffle spacing controls shell-side performance"], k: ["Cleanability decides allocation for dirty fluids", "Thermal expansion differences need floating heads or bellows"], m: ["Putting the fouling fluid on the shell side"] },
  { t: "Fouling and its effect on exchanger performance", p: "What causes fouling in exchangers and how do you design around it?", d: 2, tp: "heat-exchangers", i: "Fouling arises from scaling (precipitation of salts), particulate deposition, corrosion products, biological growth and chemical reaction such as coking, adding a thermal resistance that lowers U and raises pressure drop. Designs include fouling factors in the area calculation, higher velocities to scour deposits, easily cleanable tube layouts, filtration and chemical treatment, and cleaning schedules. Too large a fouling margin wastes capital while too small a margin shortens run length.", c: ["Scaling, particulates, corrosion, biological growth and reaction", "Adds thermal resistance and raises pressure drop", "Fouling factors, velocity, cleanable layout", "Filtration, treatment and cleaning schedules"], k: ["Surface temperature affects deposition rate", "Fouling factors are estimated from experience"], m: ["Designing a clean exchanger with no margin"] },
  { t: "Heat exchanger temperature cross and approach", p: "What is a temperature cross, and why can a single-pass shell-and-tube unit not handle it well?", d: 3, tp: "heat-exchangers", i: "A temperature cross occurs when the cold stream's outlet temperature exceeds the hot stream's outlet temperature, which is possible in counter-current flow but not in co-current. Shell-and-tube units with multiple tube passes behave partly co-current, reducing the correction factor F_T on LMTD; if F_T falls below about 0.8, the unit is inefficient. Use multiple shells in series or true counter-current designs such as plate exchangers to handle crossing temperatures.", c: ["Cold outlet hotter than hot outlet is a cross", "Possible only in counter-current flow", "Multi-pass units have an F_T correction below one", "Shells in series or plate exchangers handle crosses"], k: ["A low F_T signals poor use of area", "Close approach temperatures need large area"], m: ["Using co-current flow for a temperature cross"] },
  { t: "Plate versus shell-and-tube exchangers", p: "When is a plate heat exchanger the better choice, and what are its limits?", d: 2, tp: "heat-exchangers", i: "Plate exchangers give high heat transfer coefficients through turbulence in narrow channels, compact size, close approach temperatures and easy inspection and cleaning by opening the frame, so they suit liquid-liquid duties at moderate pressure and temperature, such as in food and HVAC. Limits are gasket temperature and pressure ratings, susceptibility to blockage by particles and fibres, and unsuitability for gases and large volume flows with low allowed pressure drop.", c: ["High coefficients and compact size", "Easy cleaning and expansion", "Gasket temperature and pressure limits", "Not suitable for particles, fibres or low-pressure-drop gases"], k: ["Welded or brazed plates extend ratings", "Close temperature approaches save energy"], m: ["Using gasketed plates with aggressive fluids at high temperature"] },
  { t: "Boiling and condensation in process heat exchangers", p: "What design issues arise in reboilers and condensers compared with single-phase exchangers?", d: 3, tp: "heat-exchangers", tp2: "heat-transfer", i: "Phase change gives high heat transfer coefficients but adds complexity: reboilers must avoid exceeding critical heat flux (film boiling) and ensure stable circulation in thermosiphon designs, while condensers handle vapour velocity, venting of non-condensable gases that blanket the surface and condensate subcooling. Mixtures condense or boil over a temperature range, so the temperature profile is non-linear and LMTD needs care.", c: ["High coefficients from phase change", "Reboilers must stay below critical heat flux", "Non-condensables blanket condenser surfaces", "Mixtures give non-linear temperature profiles"], k: ["Vent design is essential for condensers", "Thermosiphon stability depends on piping layout"], m: ["Ignoring non-condensable gases"] },
  { t: "Double-pipe and air-cooled exchangers", p: "When would you use an air-cooled exchanger instead of water-cooled one?", d: 1, tp: "heat-exchangers", i: "Air coolers avoid the need for cooling water supply, treatment and discharge, so they suit sites with scarce water or strict discharge limits and remove heat to ambient air, but require large finned surface because air has low heat transfer coefficient and heat capacity. Process outlet temperatures cannot go below ambient dry-bulb plus an approach of about 15 to 20 K, and fans consume electric power and make noise.", c: ["No cooling water required", "Large finned area due to air properties", "Outlet limited by ambient dry-bulb plus approach", "Fan power and noise"], k: ["Hot weather limits capacity", "Trim cooling with water may be needed in summer"], m: ["Expecting air cooling to reach water-cooled temperatures"] },
  { t: "Thermal design of heat exchanger networks for energy recovery", p: "How would you recover waste heat from a flue gas stream, and what limits its use?", d: 2, tp: "heat-exchangers", tp2: "thermodynamics", i: "Heat can preheat combustion air, feed water or process streams using economisers or recuperators. Limits include acid dew point (condensation of sulfuric acid in flue gas leading to corrosion), fouling by ash, low temperature difference and the distance to a heat sink. Economics depend on recoverable duty, capital cost and payback period compared with fuel savings.", c: ["Preheat air, feed water or process streams", "Acid dew point causes corrosion", "Fouling and low temperature differences", "Economic payback decides"], k: ["Match heat source temperature to the sink", "Materials selection handles corrosion"], m: ["Cooling flue gas below the acid dew point without protection"] },
  { t: "Effectiveness and capacity ratio in heat exchangers", p: "How does the heat capacity rate ratio influence exchanger effectiveness?", d: 3, tp: "heat-exchangers", tp2: "heat-transfer", i: "The capacity ratio C_r = C_min/C_max measures how unbalanced the streams are. When C_r is small, the stream with large capacity barely changes temperature, so effectiveness approaches 1 − exp(−NTU) regardless of flow arrangement. When C_r is near one, counter-current gives much higher effectiveness than co-current for the same NTU. At C_r = 0, as in boiling or condensing, effectiveness is the same for all arrangements.", c: ["Cr = Cmin/Cmax", "Small Cr makes arrangement matter less", "Counter-current outperforms co-current at high Cr", "Cr = 0 for phase change gives the same effectiveness"], k: ["NTU measures exchanger size relative to Cmin", "Effectiveness is bounded by 1"], m: ["Using the same correlation for every arrangement"] },
  // ---- Process control ----
  { t: "Tuning a PI controller on a flow loop", p: "How would you tune a flow control loop, and why is it different from a level loop?", d: 1, tp: "process-control", i: "Flow loops respond almost instantly with little lag, so use a PI controller with moderate gain and fast integral time (seconds), and no derivative because of noise. Level loops are integrating processes, and often only need a proportional or loosely tuned PI controller, because tight control causes outlet flow swings to downstream units; averaging level control uses the tank as a buffer. Tune by step test and a method such as IMC or Ziegler-Nichols with adjustment.", c: ["Flow loop is fast and PI is typical", "No derivative because of noise", "Level loops are integrating and can use loose control", "Tune by step test and adjust"], k: ["Valve stiction affects flow loops", "Averaging level control protects downstream units"], m: ["Tuning a level loop as tightly as a flow loop"] },
  { t: "Ziegler-Nichols and process reaction curve tuning", p: "Describe two classical ways to get PID settings from process tests and their limitations.", d: 2, tp: "process-control", i: "The ultimate-gain method raises proportional gain until sustained oscillation, then uses the ultimate gain and period for settings, but pushes the process to the edge of instability. The process reaction curve method applies a step in the manipulated variable and fits a first-order plus dead time model to get gain, time constant and delay, then applies tuning rules. Both give aggressive settings with a quarter-amplitude decay that often needs detuning for robustness.", c: ["Ultimate gain method uses sustained oscillation", "Reaction curve fits a first-order plus delay model", "Settings from tuning rules", "Often too aggressive and need detuning"], k: ["Dead time to time-constant ratio guides tuning", "Open-loop tests are safer"], m: ["Running ultimate-gain tests on safety-critical loops"] },
  { t: "Ratio control and blending", p: "How would you control the blend of two streams to a fixed ratio?", d: 2, tp: "process-control", i: "Measure the wild stream and multiply by the ratio setpoint to set the flow controller setpoint of the manipulated stream, so changes in the wild flow automatically adjust the other. Trim the ratio from a downstream composition or property analyser using a slower outer loop. This feedforward-like structure rejects flow disturbances quickly, while the trim fixes metering errors and composition drift.", c: ["Measure the wild stream and scale to set the other flow", "Ratio setpoint multiplies the measured flow", "Analyser trim on the ratio", "Fast flow disturbance rejection"], k: ["Both flow measurements must be accurate", "Analyser delay requires slow trim"], m: ["Controlling both flows independently"] },
  { t: "Feedforward control in process plants", p: "Where does feedforward control give the biggest benefit in a process, and what are the practical difficulties?", d: 2, tp: "process-control", i: "Feedforward helps when a measurable disturbance, such as feed flow or composition, affects a slow or delayed process variable, because it adjusts the manipulated variable before the process variable moves. It needs an accurate process model, with dynamic compensation (lead-lag and delay) to time the correction properly. Model errors leave residual error, so feedback trim is added.", c: ["Measurable disturbance affecting a slow process", "Acts before the error appears", "Needs a model and dynamic compensation", "Feedback trim handles residual errors"], k: ["Poor timing can make things worse", "Static-only feedforward is a first step"], m: ["Using feedforward without a feedback loop"] },
  { t: "Distillation column control structures", p: "Outline a typical control scheme for a distillation column and common interaction problems.", d: 3, tp: "process-control", tp2: "mass-transfer", i: "Typical schemes control pressure with condenser duty or vapour bypass, reflux drum and sump levels with distillate and bottoms flows or reflux and boilup, and product composition indirectly by tray temperature controlling reflux or boilup. Interactions between top and bottom composition loops are strong, so schemes use decoupling or careful pairing, such as the L/V configuration, and one-point composition control when only one product is critical.", c: ["Pressure control by condenser duty", "Level control of drum and sump", "Tray temperature as an inferential composition measurement", "Loop interaction and decoupling"], k: ["Temperature is faster than composition analysers", "Pairing choice changes sensitivity"], m: ["Controlling both product compositions independently without regard to interaction"] },
  { t: "Control valve failure position and safe design", p: "How do you choose whether a control valve fails open or closed?", d: 1, tp: "process-control", tp2: "process-safety", i: "Choose the failure position that leads to the safest process state if air or signal is lost: a heating steam valve should fail closed, a cooling water valve fail open, a reflux valve to a column often fail open and a feed to a reactor fail closed. Document the logic in the P&ID and verify during HAZOP, and consider the failure of related instruments.", c: ["Choose the safest state on loss of signal or air", "Steam fails closed and cooling water fails open", "Reactor feed fails closed", "Verify in HAZOP and document on the P&ID"], k: ["Spring action sets the failure position", "Consider the effect on the whole unit, not one loop"], m: ["Defaulting to fail-closed for all valves"] },
  { t: "Cascade control in reactor temperature control", p: "Why is cascade control commonly used for jacketed reactor temperature?", d: 2, tp: "process-control", tp2: "reaction-engineering", i: "The reactor temperature responds slowly to the jacket coolant flow, while jacket temperature responds quickly and picks up utility disturbances, such as coolant supply temperature changes. An inner loop controls jacket temperature fast, rejecting those disturbances, and the outer loop sets the jacket setpoint from the reactor temperature error. This improves disturbance rejection and tolerance to valve nonlinearity.", c: ["Slow primary variable with a faster secondary", "Inner loop rejects utility disturbances", "Outer loop sets the inner setpoint", "Better disturbance rejection and nonlinearity tolerance"], k: ["Inner loop must be faster than the outer", "Secondary measurement must be available"], m: ["Making the inner loop as slow as the outer loop"] },
  { t: "Model predictive control in the process industries", p: "What does MPC offer over multiple PID loops, and what are its requirements?", d: 3, tp: "process-control", i: "MPC uses a dynamic model to predict future outputs over a horizon and optimises a sequence of moves subject to constraints on inputs and outputs, so it handles multivariable interactions, constraints and economic objectives directly. Requirements are a reasonably accurate model identified from plant tests, reliable instrumentation, a base layer of stable regulatory control and engineering support to maintain it as the plant changes.", c: ["Predicts outputs over a horizon", "Optimises moves under constraints", "Handles multivariable interaction", "Needs models, stable base control and maintenance"], k: ["Model drift degrades performance", "Operating near constraints delivers the economic benefit"], m: ["Deploying MPC on top of poorly performing base loops"] },
  { t: "Alarm management principles", p: "What makes an alarm system effective, and what problems come from alarm floods?", d: 2, tp: "process-control", tp2: "ergonomics", i: "Each alarm should be relevant, unique, timely, prioritised, understandable and require an operator action, with a documented response. Alarm floods happen when too many alarms occur in a short time, as a cascade from one upset, so operators miss critical ones. Rationalisation removes nuisance alarms, sets thresholds with deadbands and delays, suppresses consequential alarms, and monitors performance (alarms per operator per hour, standing alarms).", c: ["Relevant, prioritised alarms requiring action", "Floods hide critical alarms", "Rationalisation, deadbands and delays", "Performance monitoring metrics"], k: ["Standards such as ISA-18.2 guide practice", "Operator workload limits the alarm rate"], m: ["Adding an alarm for every deviation"] },
  { t: "Inferential measurement and soft sensors", p: "What is a soft sensor, and when is it used in process plants?", d: 2, tp: "process-control", tp2: "machine-learning", i: "A soft sensor estimates a hard-to-measure quantity, such as product composition, from easily measured variables like temperatures, pressures and flows using a first-principles or data-driven model. It gives fast, continuous estimates that analysers with long delays cannot, enabling better control, and is corrected periodically with laboratory results. Risks are drift, operation outside the training range and sensor failure, so validation and monitoring are required.", c: ["Estimates unmeasured variables from measured ones", "First-principles or data-driven models", "Corrected with lab data", "Drift and extrapolation risk"], k: ["Fast estimates enable tighter control", "Model maintenance is an ongoing task"], m: ["Trusting the soft sensor outside its training range"] },
  { t: "Stability analysis of a first-order-plus-dead-time process under PI control", p: "How does the ratio of dead time to time constant influence achievable control performance?", d: 3, tp: "process-control", tp2: "control-theory", i: "When dead time is small relative to the time constant, a tightly tuned PI controller can give fast response and good disturbance rejection. When the ratio approaches or exceeds one, the process is dead-time dominated: the loop gain must be small to keep margins, so the response is slow and integral action does most of the work. Dead-time compensators such as a Smith predictor can help with accurate models.", c: ["Dead time to time constant ratio determines difficulty", "Small ratio allows tight tuning", "Large ratio forces low gain and slow response", "Smith predictor with an accurate model helps"], k: ["Delay adds phase lag proportional to frequency", "Reducing the delay physically is best"], m: ["Increasing gain to speed up a dead-time-dominated loop"] },
  // ---- Process economics and design ----
  { t: "Process flow diagram versus P&ID", p: "What information appears on a PFD versus a P&ID and how are they used?", d: 1, tp: "process-control", tp2: "process-safety", i: "A PFD shows major equipment, main process streams, flow rates, temperatures, pressures and compositions from the heat and material balance, for understanding the process concept and costing. A P&ID adds detail: all lines with sizes and specifications, valves, instrumentation and control loops, safety devices, vents and drains, used for detailed design, HAZOP, construction and operation.", c: ["PFD shows major equipment and balances", "P&ID shows lines, valves and instruments", "PFD for concept and costing", "P&ID for design, HAZOP and operation"], k: ["Tag numbering links documents", "Revisions must be controlled"], m: ["Treating the PFD as enough for construction"] },
  { t: "Capital cost estimation and scaling", p: "How do the six-tenths rule and Lang factors estimate plant capital cost, and how accurate are they?", d: 2, tp: "process-control", i: "The six-tenths rule scales equipment cost with capacity: Cost2 = Cost1 × (Capacity2/Capacity1)^0.6, reflecting economies of scale. Lang or similar factors multiply the purchased equipment cost to estimate total installed plant cost, including piping, instruments, construction and contingency. These are order-of-magnitude (±30 percent) estimates used in feasibility, refined later by detailed engineering and quotations.", c: ["Six-tenths rule for capacity scaling", "Lang factors multiply equipment cost", "Includes installation and contingency", "Accuracy of about ±30 percent for early estimates"], k: ["Cost indexes update historical costs", "Exponent varies by equipment type"], m: ["Treating early estimates as firm"] },
  { t: "Green chemistry and process intensification", p: "What does process intensification aim to achieve and give one example.", d: 2, tp: "reaction-engineering", tp2: "environmental-regulation", i: "Intensification aims to make processes substantially smaller, safer, more energy-efficient and less wasteful by combining functions or improving transport, using techniques such as microreactors with very high surface-to-volume ratios, reactive distillation (reaction and separation in one unit), rotating packed beds and membrane reactors. Benefits are better heat control, lower inventory and safer operation, with challenges in fouling, scale-up and capital cost for novel equipment.", c: ["Smaller, safer and more efficient processes", "Microreactors improve heat and mass transfer", "Reactive distillation combines reaction and separation", "Challenges: fouling, scale-up and novelty"], k: ["Lower inventory is inherently safer", "Numbering-up replaces scale-up for microreactors"], m: ["Assuming novel equipment is risk-free"] },
  { t: "Scale-up from laboratory to pilot to plant", p: "What goes wrong when scaling a reaction from a flask to a production reactor?", d: 3, tp: "reaction-engineering", tp2: "heat-exchangers", i: "Surface-area-to-volume ratio falls with scale, so heat removal becomes limiting and exotherms cause hot spots; mixing times lengthen, so local concentration gradients change selectivity; mass transfer between phases may differ; and addition times and heating or cooling rates cannot be matched. Strategies include calorimetry to size cooling, scale-down experiments of plant mixing conditions, pilot plants and dimensionless-group scaling where possible.", c: ["Lower surface-to-volume ratio limits heat removal", "Mixing time and gradients change selectivity", "Mass transfer differs with scale", "Calorimetry, pilot plants and scale-down tests"], k: ["No single scaling criterion preserves everything", "Safety margins change with inventory"], m: ["Assuming the lab recipe scales by simply multiplying volumes"] },
  { t: "Material and energy balance strategy for a process flowsheet", p: "How do you organise a mass and energy balance for a multi-unit process with a recycle?", d: 2, tp: "chem-thermodynamics", tp2: "reaction-engineering", i: "Draw the flowsheet with a system boundary, label streams and choose a basis. Count degrees of freedom to confirm the problem is solvable, write balances for each unit and the overall system, and handle the recycle by tearing a stream and iterating or solving algebraically using overall balances and the split fractions. The purge stream prevents buildup of inerts. Check by closing the overall balance.", c: ["Flowsheet, basis and system boundary", "Degrees of freedom analysis", "Tear a recycle stream or solve algebraically", "Purge prevents inert buildup and overall balance checks results"], k: ["Overall balances ignore recycle internals", "Conversion per pass differs from overall conversion"], m: ["Forgetting that recycle raises per-pass flows"] },
  { t: "Overall versus single-pass conversion with recycle", p: "Why can a reactor with low single-pass conversion still give high overall conversion?", d: 2, tp: "reaction-engineering", i: "Unreacted feed is separated from product and recycled to the reactor inlet, so reactant leaves the process only through product conversion or purge. Overall conversion can approach 100 percent while single-pass conversion is low, which is common for equilibrium-limited reactions such as ammonia synthesis. The costs are separation, recycle compression and larger flows through the loop.", c: ["Separation and recycle of unreacted feed", "Overall conversion can exceed single-pass conversion", "Common for equilibrium-limited reactions", "Costs: separation, compression and larger loop flows"], k: ["Purge limits inert accumulation", "Recycle ratio affects equipment sizing"], m: ["Equating reactor conversion with process conversion"] },
  { t: "Le Chatelier's principle in reactor design", p: "How do temperature and pressure choices affect equilibrium yield for ammonia synthesis?", d: 2, tp: "chem-thermodynamics", tp2: "reaction-engineering", i: "Ammonia synthesis is exothermic and reduces the number of moles, so equilibrium conversion rises with lower temperature and higher pressure. But low temperature slows the reaction, so a compromise near 400 to 500 °C is used with an iron catalyst, and high pressure (150 to 300 bar) raises equilibrium conversion at the cost of compression. Product ammonia is condensed out and unreacted gas is recycled.", c: ["Exothermic reaction favours lower temperature", "Fewer product moles favour higher pressure", "Kinetics force a compromise temperature", "Condense product and recycle unreacted gas"], k: ["Catalyst allows a lower temperature", "Compression is a major cost"], m: ["Choosing the lowest temperature for the highest equilibrium without regard to rate"] },
  { t: "Heat of mixing and solution behaviour", p: "Why do some liquids heat up or cool down when mixed, and why does it matter in process design?", d: 2, tp: "chem-thermodynamics", tp2: "heat-exchangers", i: "The enthalpy of mixing reflects the difference between unlike and like molecular interactions: strong unlike attraction (negative deviation) releases heat, as with sulfuric acid in water, while weaker unlike interactions absorb heat. In design, large exothermic mixing needs cooling and controlled addition order to avoid boiling or splashing, and energy balances on mixers and distillation columns must include it for non-ideal mixtures.", c: ["Mixing enthalpy arises from unlike versus like interactions", "Strong unlike attraction releases heat", "Control addition order and cooling", "Include in energy balances for non-ideal mixtures"], k: ["Add acid to water, not water to acid", "Excess enthalpy accompanies deviation from ideality"], m: ["Assuming mixing is always thermally neutral"] },
  { t: "Cavitation and flashing across control valves", p: "How do cavitation and flashing differ in control valves, and what damage do they cause?", d: 3, tp: "fluid-transport", tp2: "process-control", i: "Both occur when pressure inside the valve (at the vena contracta) falls below the vapour pressure. In cavitation, downstream pressure recovers above vapour pressure, so the vapour bubbles collapse violently, causing noise, vibration and pitting. In flashing, downstream pressure stays below vapour pressure, so vapour persists, causing high-velocity erosion on the valve body and downstream. Remedies include anti-cavitation trims, staged pressure drop, hardened materials and larger valves.", c: ["Pressure at the vena contracta drops below vapour pressure", "Cavitation: bubbles collapse downstream", "Flashing: vapour persists downstream", "Staged drop trims and hard materials"], k: ["Recovery factor indicates the severity", "Downstream piping may need to be larger for flashing"], m: ["Treating cavitation and flashing as the same problem"] },
  { t: "Selecting materials of construction for corrosive services", p: "What factors guide the choice between carbon steel, stainless steel and alloys for a chemical plant?", d: 2, tp: "process-safety", tp2: "corrosion", i: "Evaluate fluid composition, concentration, temperature and velocity, presence of chlorides, acids or caustic, and risk of stress corrosion cracking or erosion-corrosion. Carbon steel is cheap and fine in many non-corrosive services with a corrosion allowance, stainless steels offer broader resistance but can fail by chloride pitting and cracking, and nickel alloys, titanium or lined vessels serve severe cases. Decide by life-cycle cost, considering inspection and replacement.", c: ["Fluid chemistry, temperature and velocity", "Carbon steel with corrosion allowance for mild services", "Stainless steels have chloride limits", "Alloys or linings for severe service and life-cycle cost"], k: ["Corrosion data and experience support selection", "Weld areas are often more vulnerable"], m: ["Using stainless steel in any corrosive service without checking chlorides"] },
  { t: "Gas-liquid separators and demisters", p: "How do you size a vertical gas-liquid separator, and what limits throughput?", d: 2, tp: "fluid-transport", tp2: "mass-transfer", i: "The gas velocity must be below the terminal settling velocity of the droplets to be removed, using the Souders-Brown equation v = K√((ρL − ρG)/ρG), which sets the vessel diameter, while height provides liquid hold-up, surge volume and disengagement space. Mist eliminators allow a higher K by capturing fine droplets. Excess gas velocity causes carryover of liquid, and foaming makes it worse.", c: ["Gas velocity below the droplet terminal velocity", "Souders-Brown equation sets diameter", "Height provides surge and disengagement", "Mist eliminators capture fine droplets"], k: ["Carryover damages downstream equipment", "Foaming needs extra capacity or antifoam"], m: ["Sizing only for liquid residence time"] },
  { t: "Heat transfer in agitated vessels and jackets", p: "What limits heat removal in a jacketed stirred reactor and how can you increase it?", d: 2, tp: "heat-exchangers", tp2: "reaction-engineering", i: "Overall heat transfer is limited by the inside film coefficient (set by agitation and viscosity), the vessel wall and fouling, and the jacket-side coefficient, and by the available area, which grows with the square of scale while volume grows with the cube. Improve with better agitation, an internal coil or external heat exchanger loop, higher jacket flow, lower coolant temperature or dimpled/half-pipe jackets.", c: ["Inside film, wall, fouling and jacket resistances", "Area-to-volume ratio falls at larger scale", "Better agitation and internal coils", "External loop exchanger as an alternative"], k: ["Viscosity increases during polymerisation lower the coefficient", "Coolant temperature limit protects against freezing"], m: ["Relying on the jacket alone at large scale"] },
  { t: "Safe operation of batch reactors: charge order and hold points", p: "What operational controls prevent accidents in batch chemical production?", d: 2, tp: "process-safety", tp2: "reaction-engineering", i: "Define the correct sequence and quantities of charging with interlocks and verified measurements, prevent addition of reagents in the wrong order, hold at specified temperatures with checks before moving on, limit feed rates of exothermic reagents, verify agitation is running before charging, and keep documented procedures with operator training. Batch-to-batch deviations such as skipped agitation have caused major runaway incidents.", c: ["Verified sequence and quantities with interlocks", "Check agitation before reagent addition", "Limit feed rates of exothermic reagents", "Documented procedures and training"], k: ["Accumulation of unreacted reagent is the main runaway cause", "Operator error is reduced by design controls"], m: ["Relying on the operator to remember critical steps"] },
  { t: "Environmental controls: scrubbers and thermal oxidisers for process emissions", p: "How would you control a process vent containing volatile organic compounds and acid gas?", d: 2, tp: "mass-transfer", tp2: "air-quality", i: "Treat acid gases first in a wet scrubber with caustic solution, which absorbs and neutralises them, then use a thermal or catalytic oxidiser to destroy the VOCs, with heat recovery to reduce fuel use. Alternatives include carbon adsorption with regeneration, condensation or biofiltration depending on concentration and flow. Choose based on destruction efficiency required, concentration, flow variability and costs.", c: ["Wet scrubber absorbs acid gases", "Thermal or catalytic oxidiser destroys VOCs", "Heat recovery reduces fuel use", "Adsorption, condensation or biofiltration alternatives"], k: ["Acid gas can poison catalysts or corrode oxidisers", "Low concentration streams favour adsorption concentration first"], m: ["Sending acid gas straight to a thermal oxidiser without scrubbing"] },
  { t: "Utility systems: steam, cooling water and compressed air", p: "Why do process plants need a utility system and what drives its design?", d: 1, tp: "heat-exchangers", tp2: "thermodynamics", i: "Utilities supply heating (steam at several pressure levels), cooling (water, air or refrigerant), power, compressed air, nitrogen and water. Design follows the heat and cooling demand at various temperatures from heat integration, with boiler and cooling tower capacity, headers, condensate return and redundancy for reliability. Efficient design matches steam levels to process needs and recovers condensate.", c: ["Steam, cooling, power and gases", "Capacity from process heat and cooling demands", "Condensate return and redundancy", "Match utility levels to process needs"], k: ["Utility cost is a large share of operating cost", "Failure of utilities is a main source of plant upsets"], m: ["Sizing utilities without considering peak demand"] },
  { t: "Flare systems and relief headers", p: "How does a flare system protect a plant and what limits its capacity?", d: 3, tp: "process-safety", tp2: "fluid-transport", i: "Relief devices discharge to a header that leads to a knockout drum, which removes liquids, then to a flare stack where the gas is burned safely. Capacity is limited by header back-pressure (which can reduce relief valve capacity), flame radiation at ground level and noise, so the largest simultaneous relief scenario sets the header and flare size, with a smokeless burning aid such as steam. Flare tip velocity and purge gas maintain stable burning and avoid air ingress.", c: ["Relief devices discharge to a header, knockout drum and flare", "Header back-pressure limits relief valve capacity", "Radiation and noise limit siting", "Largest simultaneous scenario sets the size"], k: ["Liquids in the flare can cause burning rain", "Purge gas prevents flashback"], m: ["Sizing the flare for a single relief device only"] },
  { t: "Statistical process control in chemical production", p: "How would you use control charts on a continuous chemical process?", d: 2, tp: "process-control", tp2: "quality-spc", i: "Chart key quality variables such as product purity or viscosity on individual-moving-range or EWMA charts since continuous processes often yield single measurements, establishing limits from stable data. Rules flag shifts, trends or points outside limits, prompting investigation of special causes such as feed change or catalyst decay, and the charts separate real process shifts from normal variation to avoid over-adjustment by operators.", c: ["Individuals and moving-range or EWMA charts", "Limits from stable data", "Rules detect shifts and trends", "Avoid over-adjusting for common-cause variation"], k: ["Autocorrelation can violate chart assumptions", "Control limits differ from specifications"], m: ["Reacting to every point inside the limits"] },
  { t: "Distillation versus membrane or adsorption for dehydration of ethanol", p: "Why can ethanol not be dehydrated beyond about 95.6 percent by simple distillation and what are the alternatives?", d: 3, tp: "mass-transfer", tp2: "chem-thermodynamics", i: "Ethanol and water form a minimum-boiling azeotrope at about 95.6 weight percent ethanol, where vapour and liquid have equal composition, so distillation cannot go further. Alternatives are azeotropic or extractive distillation with an entrainer, molecular-sieve adsorption (pressure swing) which selectively adsorbs water, and pervaporation membranes. Sieve adsorption is common for fuel-grade ethanol because it avoids entrainer handling and uses less energy.", c: ["Azeotrope near 95.6 percent ethanol", "Distillation cannot cross it", "Entrainer-based distillation as an option", "Molecular sieves or membranes are common"], k: ["Pressure changes azeotrope composition slightly", "Regeneration energy drives adsorbent cost"], m: ["Adding more trays to pass an azeotrope"] },
  { t: "Interpreting a pump performance test", p: "How would you evaluate whether a pump is operating healthily using plant data?", d: 2, tp: "fluid-transport", i: "Measure flow, suction and discharge pressure, power draw and speed, compute total head and efficiency and compare with the manufacturer's curve. A drop in head or flow at the same speed suggests wear or internal recirculation, high power with low flow points to blockage or wrong operating point, and noise with vibration points to cavitation or misalignment. Trend vibration, bearing temperature and seal condition over time.", c: ["Measure flow, pressures, power and speed", "Compare with the pump curve", "Lower head at the same speed suggests wear", "Vibration and noise indicate cavitation or misalignment"], k: ["Operating off the best efficiency point shortens life", "Trending reveals gradual degradation"], m: ["Judging a pump from the motor current alone"] },
  { t: "Reaction calorimetry in process development", p: "What does reaction calorimetry measure and how is it used for safety and scale-up?", d: 3, tp: "reaction-engineering", tp2: "process-safety", i: "A reaction calorimeter measures heat release rate versus time under controlled conditions, giving total heat of reaction, heat release profile, heat transfer coefficient and adiabatic temperature rise. These data size the cooling system, set safe dosing rates, identify accumulation of unreacted reagent and show the potential for runaway, with the time to maximum rate under adiabatic conditions. They are essential for scaling exothermic reactions safely.", c: ["Measures heat release rate and total heat", "Gives heat transfer coefficient and adiabatic rise", "Identifies reagent accumulation", "Used to size cooling and set dosing rates"], k: ["Dosing-controlled operation limits accumulation", "Thermal stability tests complement calorimetry"], m: ["Scaling an exothermic process without calorimetry data"] },
];
